  function avatarChanged(u){window.ntAvatarUrl=u||'';try{if(u)rawSet.call(localStorage,'ntavatar',u);else localStorage.removeItem('ntavatar')}catch(e){}try{window.dispatchEvent(new Event('nt-avatar'))}catch(e){}}
  async function signAvatar(path){
    var r=await realFetch(SB_URL+'/storage/v1/object/sign/avatars/'+path.split('/').map(encodeURIComponent).join('/'),{method:'POST',headers:{apikey:SB_KEY,Authorization:'Bearer '+(await token()),'Content-Type':'application/json'},body:JSON.stringify({expiresIn:60*60*24*30})});
    if(!r.ok)return '';var d=await r.json();return d.signedURL?SB_URL+'/storage/v1'+d.signedURL:'';
  }
  async function loadAvatar(){
    try{var rows=await rest('GET','profiles?id=eq.'+session.user.id+'&select=avatar_path');var p=rows&&rows[0]&&rows[0].avatar_path;avatarChanged(p?await signAvatar(p):'')}catch(e){}
  }
  async function squareJpeg(file,size){
    var bmp=await createImageBitmap(file);var c=document.createElement('canvas');c.width=c.height=size;
    var s=Math.max(size/bmp.width,size/bmp.height),w=bmp.width*s,h=bmp.height*s;var x=c.getContext('2d');x.imageSmoothingQuality='high';x.drawImage(bmp,(size-w)/2,(size-h)/2,w,h);
    return await new Promise(function(res,rej){c.toBlob(function(b){b?res(b):rej(new Error('Couldn\u2019t read that photo'))},'image/jpeg',.85)});
  }
  window.ntSetAvatar=async function(file){
    var uid=session.user.id,blob=await squareJpeg(file,480),path=uid+'/'+Date.now().toString(36)+'.jpg';
    var r=await realFetch(SB_URL+'/storage/v1/object/avatars/'+uid+'/'+path.split('/')[1],{method:'POST',headers:{apikey:SB_KEY,Authorization:'Bearer '+(await token()),'Content-Type':'image/jpeg','x-upsert':'true'},body:blob});
    if(!r.ok)throw new Error('Upload failed. Please try again.');
    var old=await rest('GET','profiles?id=eq.'+uid+'&select=avatar_path');old=old&&old[0]&&old[0].avatar_path;
    await rest('PATCH','profiles?id=eq.'+uid,{avatar_path:path},{Prefer:'return=minimal'});
    if(old&&old!==path)realFetch(SB_URL+'/storage/v1/object/avatars',{method:'DELETE',headers:{apikey:SB_KEY,Authorization:'Bearer '+(await token()),'Content-Type':'application/json'},body:JSON.stringify({prefixes:[old]})}).catch(function(){});
    avatarChanged(await signAvatar(path));
  };
  window.ntRemoveAvatar=async function(){
    var uid=session.user.id,old=await rest('GET','profiles?id=eq.'+uid+'&select=avatar_path');old=old&&old[0]&&old[0].avatar_path;
    await rest('PATCH','profiles?id=eq.'+uid,{avatar_path:null},{Prefer:'return=minimal'});
    if(old)realFetch(SB_URL+'/storage/v1/object/avatars',{method:'DELETE',headers:{apikey:SB_KEY,Authorization:'Bearer '+(await token()),'Content-Type':'application/json'},body:JSON.stringify({prefixes:[old]})}).catch(function(){});
    avatarChanged('');
  };



  /* ---------- leaderboard score (last 7 days, shared with other members) ---------- */
  // 10 for using the app that day, 5 for logging food, 5 for 8+ glasses of water,
  // 1 per 1,000 steps (max 15), 15 per workout.
  function weekScore(get){
    var act=get('active-days',{})||{},hab=get('habits-history',{})||{},steps=get('steps-log',{})||{},ws=get('workout-sessions',[])||[];
    var score=0,steps7=0,wk=0,streak=0,days=[];
    for(var i=0;i<7;i++){var d=new Date(Date.now()-i*864e5).toISOString().slice(0,10);days.push(d)}
    days.forEach(function(d){
      var food=get('food-log-'+d,[]),w=(Array.isArray(ws)?ws:[]).filter(function(x){return x&&x.date===d}).length,st=Number(steps[d])||0;
      score+=(act[d]?10:0)+(Array.isArray(food)&&food.length?5:0)+((Number((hab[d]||{}).water)||0)>=8?5:0)+Math.min(15,Math.floor(st/1000))+15*w;
      steps7+=st;wk+=w;
    });
    for(var j=act[days[0]]?0:1;j<365;j++){var dd=new Date(Date.now()-j*864e5).toISOString().slice(0,10);if(act[dd])streak++;else break}
    return {score:score,steps7:steps7,workouts7:wk,streak:streak};
  }
  window.ntWeekScore=weekScore;
  var lastScore='';
  async function publishScore(){
    if(!session)return;
    var get=function(k,f){try{var v=lsGet('nt:'+k);return v?JSON.parse(v):f}catch(e){return f}};
    var p=get('profile',{})||{};if(!p.name)return;
    var doc=Object.assign({name:String(p.name).slice(0,40),avatar:!!window.ntAvatarUrl},weekScore(get));
    var key=JSON.stringify(doc);if(key===lastScore)return;
    try{await rest('POST','shared_docs?on_conflict=collection,doc_id',[{collection:'scores',doc_id:session.user.id,data:Object.assign(doc,{updatedAt:new Date().toISOString()})}],{Prefer:'resolution=merge-duplicates,return=minimal'});lastScore=key}catch(e){}
  }
  window.ntLeaderboard=async function(){
    var rows=await rest('GET','shared_docs?collection=eq.scores&select=doc_id,data&limit=2000');
    var weekAgo=new Date(Date.now()-8*864e5).toISOString();
    var hid=hiddenIds();
    return (rows||[]).filter(function(r){return hid.indexOf(r.doc_id)<0}).map(function(r){return Object.assign({id:r.doc_id,me:session&&r.doc_id===session.user.id},r.data)})
      .map(function(x){if(!x.updatedAt||x.updatedAt<weekAgo){x.score=0}return x})
      .sort(function(a,b){return (b.score||0)-(a.score||0)||String(a.name).localeCompare(String(b.name))});
  };
  setInterval(function(){if(document.visibilityState==='visible')publishScore()},120000);


  /* ---------- report or hide another member (Google Play user-generated content rules) ---------- */
  function hiddenIds(){try{return JSON.parse(localStorage.getItem('nt-hidden')||'[]')}catch(e){return []}}
  window.ntMemberAction=function(m){
    var w=document.createElement('div');w.className='nt-ai-notice';w.setAttribute('role','dialog');w.setAttribute('aria-modal','true');w.setAttribute('aria-label','Options for '+(m.name||'this member'));
    var nm=String(m.name||'this member').replace(/[<>&"]/g,'');
    w.innerHTML='<style>'+AI_CSS+'</style><div class="nt-ai-card"><b>'+nm+'</b><p>Report them if their name or photo is offensive or they are harassing you. Hiding removes them from your leaderboard and squad on this device.</p><div class="nt-ai-btns" style="grid-template-columns:1fr 1fr 1fr"><button type="button" data-a="no">Cancel</button><button type="button" data-a="hide">Hide</button><button type="button" data-a="report">Report</button></div></div>';
    document.body.appendChild(w);
    w.onclick=async function(e){var a=e.target.getAttribute&&e.target.getAttribute('data-a');if(!a&&e.target!==w)return;w.remove();
      if(a==='hide'||a==='report'){var h=hiddenIds();if(h.indexOf(m.id)<0){h.push(m.id);localStorage.setItem('nt-hidden',JSON.stringify(h))}}
      if(a==='report'){var why=await window.ntPrompt('What’s the problem? (optional)','');if(why===null)why='';
        try{await rest('POST','reports',{user_id:session.user.id,kind:'member',target:m.id,content:String(m.name||'').slice(0,200),reason:why.trim().slice(0,1000)},{Prefer:'return=minimal'});window.ntToast('Reported and hidden. Your coach will review it.')}catch(err){window.ntToast('Couldn\u2019t send the report. Please try again.')}}
      else if(a==='hide')window.ntToast('Hidden from your leaderboard and squad');
      if(a==='hide'||a==='report')try{window.dispatchEvent(new Event('nt-hidden'))}catch(x){}
    };
  };

  /* ---------- changes made by the coach ---------- */
  // The coach panel saves an assigned plan as "coach-plan". It wins over the phone's copy,
  // but keeps the member's own exercise swaps.
  function applyCoachPlan(){
    var cp;try{cp=JSON.parse(lsGet('nt:coach-plan')||'null')}catch(e){cp=null}
    if(!cp||!cp.plan||!cp.assignedAt)return false;
    var cur;try{cur=JSON.parse(lsGet('nt:training-plan')||'null')}catch(e){cur=null}
    if(cur&&cur.coachAppliedAt&&cur.coachAppliedAt>=cp.assignedAt)return false;
    var next=Object.assign({},cp.plan,{swaps:(cur&&cur.swaps)||cp.plan.swaps||{},coachAppliedAt:cp.assignedAt,coachSet:true});
    lsSet('nt:training-plan',JSON.stringify(next));
    return true;
  }
  var trainingNoticeOpen=false;
  async function coachPlanNotice(){
    if(trainingNoticeOpen||!session||!window.ntAlert)return false;
    var cp,seen;try{cp=JSON.parse(lsGet('nt:coach-plan')||'null');seen=JSON.parse(lsGet('nt:coach-plan-seen')||'null')}catch(e){return false}
    if(!cp||!cp.plan||!cp.assignedAt||seen&&seen.assignedAt>=cp.assignedAt)return false;
    trainingNoticeOpen=true;
    try{
      var ok=await window.ntAlert('Your coach changed your training plan. Open Train to see your updated plan.');
      if(ok===true){lsSet('nt:coach-plan-seen',JSON.stringify({assignedAt:cp.assignedAt}));window.dispatchEvent(new Event('nt-training-plan'))}
      return true;
    }finally{trainingNoticeOpen=false}
  }
  var lastRefresh=0;
  async function refreshFromCloud(){
    if(!session||Date.now()-lastRefresh<15000)return;lastRefresh=Date.now();
    try{
      var since=lsGet('ntlastpull')||'1970-01-01T00:00:00Z';
      var rows=await rest('GET','user_data?user_id=eq.'+session.user.id+'&select=key,value,updated_at&updated_at=gt.'+encodeURIComponent(since));
      var changed=false,newest=since;
      (rows||[]).forEach(function(r){
        if(r.updated_at>newest)newest=r.updated_at;
        if(dirty[r.key])return;
        var v=typeof r.value==='string'?r.value:JSON.stringify(r.value);
        if(lsGet('nt:'+r.key)!==v){origSetSilent('nt:'+r.key,v);if(r.key!=='coach-plan')changed=true}
      });
      rawSet.call(localStorage,'ntlastpull',newest);
      if(applyCoachPlan())changed=true;
      var notified=await coachPlanNotice();
      if(changed&&!notified)window.ntToast('Your coach updated your plan',{label:'Refresh',run:function(){reloadApp()}});
    }catch(e){}
  }
  document.addEventListener('visibilitychange',function(){if(document.visibilityState==='visible'&&document.getElementById('nt-app')&&document.getElementById('nt-app').dataset.ran)refreshFromCloud()});
  setInterval(function(){if(document.visibilityState==='visible')refreshFromCloud()},30000);

  /* Display name: shown in the app and the coach panel. */
  window.ntSetDisplayName=async function(name){
    ['profile','account'].forEach(function(k){try{var o=JSON.parse(lsGet('nt:'+k)||'null');if(o&&typeof o==='object'){o.name=name;lsSet('nt:'+k,JSON.stringify(o))}}catch(e){}});
    await flush();
    try{await rest('PATCH','profiles?id=eq.'+session.user.id,{display_name:name},{Prefer:'return=minimal'})}catch(e){}
  };

  /* ---------- steps: manual entries vs Health Connect ---------- */
  // steps-log (what the app shows and scores) = the higher of steps-manual and steps-hc for each day,
  // so a walk logged by hand and also counted by the watch is never added twice.
  function readObj(k){try{var v=JSON.parse(lsGet('nt:'+k)||'{}');return v&&typeof v==='object'&&!Array.isArray(v)?v:{}}catch(e){return {}}}
  function keep120(o){var out={};Object.keys(o).sort().reverse().slice(0,120).forEach(function(k){out[k]=o[k]});return out}
  function stepMaps(){return {log:readObj('steps-log'),man:readObj('steps-manual'),hc:readObj('steps-hc')}}
  function saveSteps(m){lsSet('nt:steps-manual',JSON.stringify(keep120(m.man)));lsSet('nt:steps-hc',JSON.stringify(keep120(m.hc)));lsSet('nt:steps-log',JSON.stringify(keep120(m.log)))}
  // Days logged before this existed have no steps-manual entry: their steps-log value was all manual.
  function manualOf(m,d){return d in m.man?Number(m.man[d])||0:d in m.hc?0:Number(m.log[d])||0}
  /* Every manual step entry goes through here (set = replace the day's total, else add). Returns the steps-log map. */
  window.ntStepsWrite=async function(d,v,set){
    var m=stepMaps();
    m.man[d]=Math.max(0,Math.min(6e4,(set?0:manualOf(m,d))+(Number(v)||0)));
    m.log[d]=Math.max(m.man[d],Number(m.hc[d])||0);
    saveSteps(m);
    return m.log;
  };
  function applyHealthSteps(days){
    var m=stepMaps(),changed={};
    Object.keys(days||{}).forEach(function(d){
      if(!/^\d{4}-\d\d-\d\d$/.test(d))return;
      var n=Math.max(0,Math.min(1e5,Math.round(Number(days[d])||0)));
      if(!(d in m.man)&&!(d in m.hc)&&d in m.log)m.man[d]=Number(m.log[d])||0;
      m.hc[d]=n;
      var eff=Math.max(Number(m.man[d])||0,n);
      if((Number(m.log[d])||0)!==eff||!(d in m.log)){m.log[d]=eff;changed[d]=eff}
    });
    saveSteps(m);
    if(Object.keys(changed).length){
      // refresh open screens only after the Squad copy is saved, so they never reload a stale one
      Promise.resolve(window.ntPushSteps&&window.ntPushSteps(changed)).catch(function(){}).then(function(){try{window.dispatchEvent(new Event('nt-steps'))}catch(e){}});
    }
  }

  /* ---------- Health Connect (Android app only) ---------- */
  // The connection is a setting on this phone only (never synced): {uid,on,last}.
  var HC_KEY='nthc',hcAvail='',hcBusy=false,hcLastAuto=0;
  function hcSaved(){var s=null;try{s=JSON.parse(lsGet(HC_KEY)||'null')}catch(e){}return s&&session&&session.user&&s.uid===session.user.id?s:null}
  function hcSet(s){if(s)lsSet(HC_KEY,JSON.stringify(s));else lsDel(HC_KEY);hcEmit()}
  function hcEmit(){try{window.dispatchEvent(new Event('nt-hc'))}catch(e){}}
  function hcPost(action){if(window.ReactNativeWebView)window.ReactNativeWebView.postMessage(JSON.stringify({type:'hc',id:'hc',action:action}))}
  function hcOn(){var s=hcSaved();return !!(s&&s.on&&hcAvail==='ok')}
  window.ntHC={
    avail:function(){return hcAvail},  // 'ok', 'update' (Health Connect needs installing/updating) or '' (web, iPhone, unsupported)
    state:function(){var s=hcSaved();return {on:hcOn(),last:s&&s.last||0,busy:hcBusy}},
    connect:function(){if(hcAvail==='update'){hcPost('install');return}hcBusy=true;hcEmit();hcPost('connect')},
    sync:function(){if(!hcOn()||hcBusy)return;hcBusy=true;hcEmit();hcPost('sync')},
    disconnect:function(){hcSet(null);hcPost('disconnect');window.ntToast('Disconnected. Steps you already imported stay.')},
    settings:function(){hcPost('settings')}
  };
  window.ntHCResult=function(r){
    if(!r)return;
    if(r.status)hcAvail=r.status==='none'?'':r.status;
    if(r.action==='connect'||r.action==='sync'){
      hcBusy=false;
      var was=hcSaved();
      if(r.days&&session&&(r.action==='connect'||(was&&was.on))){
        applyHealthSteps(r.days);
        hcSet({uid:session.user.id,on:true,last:r.at||Date.now()});
        if(r.action==='connect')window.ntToast('Health Connect connected. Steps synced.');
      }else if(r.error==='denied'){
        if(was&&was.on){hcSet(null);window.ntToast('Health Connect access was turned off. Connect again to sync steps.')}
        else window.ntToast('Steps access wasn\u2019t allowed, so nothing was imported.');
      }else if(r.error&&r.action==='connect')window.ntToast('Couldn\u2019t connect to Health Connect. Please try again.');
    }
    hcEmit();
    if(r.action==='status'&&hcOn())window.ntHC.sync();
  };
  window.ntHCForeground=function(){if(window.ReactNativeWebView&&hcAvail!=='ok'){hcPost('status');return}if(hcOn()&&Date.now()-hcLastAuto>30000){hcLastAuto=Date.now();window.ntHC.sync()}};
  setInterval(function(){if(!document.hidden&&session)window.ntHCForeground()},60000);
  document.addEventListener('visibilitychange',function(){if(!document.hidden&&session)window.ntHCForeground()});
  function hcBoot(){if(window.ReactNativeWebView){hcLastAuto=Date.now();hcPost('status')}}

