    var r=await realFetch(SB_URL+'/functions/v1/delete-account',{method:'POST',headers:{'Content-Type':'application/json',apikey:SB_KEY,Authorization:'Bearer '+(await token())},body:'{}'});
    if(!r.ok)throw new Error('Delete failed');
    // the account no longer exists: forget it on this device and return to the login screen
    setTimeout(function(){saveSession(null);try{localStorage.clear()}catch(e){}reloadApp()},1200);
