  window.ntDeleteMyAccount=async function(){
    if(!session||!session.user){location.href=SITE_URL+'delete-account.html';return}
    if(!await window.ntConfirm('Delete your account?\n\nThis permanently removes your login, profile, food and weight logs, photos, messages and everything else. It can\u2019t be undone.'))return;
    var typed=await window.ntPrompt('To confirm, type DELETE');if(String(typed||'').trim().toUpperCase()!=='DELETE')return;
    try{await window.ntDeleteServerData();await window.ntAlert('Your account and data have been deleted.')}catch(e){await window.ntAlert('Couldn\u2019t delete your account. Check your connection and try again.')}
  };
  /* Deleted somewhere else (the web page, or by the coach)? Sign out here too. Only a missing account counts, not an expired login. */
  function gone(){saveSession(null);try{localStorage.clear()}catch(e){}reloadApp()}
  function banned(){saveSession(null);try{localStorage.clear();lsSet('ntbannotice','1');lsSet('ntloginrequest','1')}catch(e){}reloadApp()}
  async function accountStatus(){
    var r=await realFetch(SB_URL+'/rest/v1/rpc/account_status',{method:'POST',headers:{apikey:SB_KEY,Authorization:'Bearer '+session.access_token,'Content-Type':'application/json'},body:'{}'});
    if(!r.ok){
      var error={};try{error=await r.json()}catch(e){}
      throw new Error('Could not verify your account. Please log in again.');
    }
    return r.json();
  }
  async function checkStillExists(){
    if(!session||!session.access_token)return;
    try{var status=await accountStatus();if(status==='banned'){banned();return}if(status==='deleted'){gone();return}var r=await realFetch(SB_URL+'/auth/v1/user',{headers:{apikey:SB_KEY,Authorization:'Bearer '+session.access_token}});
      if(r.status===401||r.status===403||r.status===404){var t=await r.text();if(/not exist|not found|user_not_found/i.test(t))gone()}}catch(e){}
  }
  document.addEventListener('visibilitychange',function(){if(document.visibilityState==='visible')checkStillExists()});
  window.addEventListener('focus',checkStillExists);
