  /* Test Store bridge. Client results are previews, never backend access grants. */
  var billingPending={},billingSequence=0;
  window.ntBillingResult=function(result){var pending=result&&billingPending[result.id];if(!pending)return;delete billingPending[result.id];clearTimeout(pending.timeout);if(!session||session.user.id!==result.userId){pending.reject(new Error('Your account changed. Please reopen Premium.'));return}if(result.error)pending.reject(new Error(result.error));else pending.resolve(result)};
  window.ntBillingRequest=function(action){return new Promise(function(resolve,reject){
    if(!session||!session.user)return reject(new Error('Please sign in first.'));
    if(!window.ReactNativeWebView)return reject(new Error('Test purchases are available in the Android test build. This website is a design preview.'));
    var id='billing-'+(++billingSequence);billingPending[id]={resolve:resolve,reject:reject,timeout:setTimeout(function(){delete billingPending[id];reject(new Error('The purchase check timed out. Please try again.'))},180000)};
    window.ReactNativeWebView.postMessage(JSON.stringify({type:'revenuecat',id:id,userId:session.user.id,action:action}));
  })};
  /* ---------- AI: one-time notice, reporting ---------- */
  var AI_CSS='.nt-ai-notice{position:fixed;inset:0;z-index:9995;background:rgba(14,53,29,.3);display:flex;align-items:flex-end;justify-content:center;padding:12px}.nt-ai-card{background:#fff;border-radius:26px;padding:20px;max-width:460px;width:100%;font:14px/1.55 "Plus Jakarta Sans",system-ui,sans-serif;color:#0F2418;box-shadow:0 30px 60px -30px rgba(0,0,0,.4)}.nt-ai-card b{font-size:17px}.nt-ai-card p{margin:10px 0;color:#3D4A42}.nt-ai-card a{color:#0E351D;font-weight:600}.nt-ai-btns{display:grid;grid-template-columns:1fr 1.6fr;gap:8px;margin-top:14px}.nt-ai-btns button{border:0;border-radius:999px;padding:13px;font:700 14px "Plus Jakarta Sans",sans-serif;cursor:pointer;background:#F1F5EE;color:#0E351D}.nt-ai-btns [data-a=yes]{background:#5DBC01';
  function aiNotice(){
    return new Promise(function(res){
      var w=document.createElement('div');w.className='nt-ai-notice';w.setAttribute('role','dialog');w.setAttribute('aria-modal','true');w.setAttribute('aria-label','About AI features');
      w.innerHTML='<style>'+AI_CSS+'</style><div class="nt-ai-card"><b>About the AI features</b><p>The coach chat, recipe ideas, meal plans and food photos use AI. To answer, we send your message, the photo you choose and the profile details needed (such as your first name, goals and diet) to our AI provider, OpenAI. We don’t send your email address.</p><p>AI answers can be wrong. They are general information, not medical advice. Check nutrition estimates, and talk to your GP before big changes to diet, exercise or medication.</p><a href="'+SITE_URL+'privacy.html" target="_blank" rel="noopener">Read the privacy policy</a><div class="nt-ai-btns"><button type="button" data-a="no">Not now</button><button type="button" data-a="yes">I understand, continue</button></div></div>';
      document.body.appendChild(w);
      w.querySelector('[data-a=yes]').focus();
      w.onclick=function(e){var a=e.target.getAttribute&&e.target.getAttribute('data-a');if(!a)return;w.remove();if(a==='yes'){rawSet.call(localStorage,'ntaiok','1');res(true)}else res(false)};
    });
  }
  window.ntReportAI=async function(text){
    var why=await window.ntPrompt(text?'What was wrong with this answer? (optional)':'Paste or describe the AI answer that was wrong, unsafe or offensive:','');
    if(why===null)return false;
    if(!text&&!why.trim())return false;
    try{await rest('POST','reports',{user_id:session.user.id,kind:'ai',content:String(text||'').slice(0,4000),reason:why.trim().slice(0,1000)},{Prefer:'return=minimal'});window.ntToast('Thanks. Your coach will review it.');return true}
    catch(e){window.ntToast('Couldn\u2019t send the report. Please try again.');return false}
  };

  /* ---------- AI: send the app's Claude calls to the Supabase "ai" function ---------- */
  window.fetch=async function(url,opts){
    var u=typeof url==='string'?url:(url&&url.url)||'';
    if(u.indexOf('api.anthropic.com')===-1)return realFetch(url,opts);
    if(lsGet('ntaiok')!=='1'&&!(await aiNotice()))return new Response(JSON.stringify({type:'error',error:{type:'daily_limit',message:'AI features are off until you agree to the AI notice.'}}),{status:429,headers:{'Content-Type':'application/json'}});
    var t;try{t=await token()}catch(e){return new Response(JSON.stringify({error:{message:'Please log in again to use the coach'}}),{status:401,headers:{'Content-Type':'application/json'}})}
    var res=await realFetch(SB_URL+'/functions/v1/ai-feature-test',{method:'POST',headers:{'Content-Type':'application/json',apikey:SB_KEY,Authorization:'Bearer '+t},body:opts&&opts.body,signal:opts&&opts.signal});
    try{
      var left=res.headers.get('x-ai-remaining'),kind=res.headers.get('x-ai-kind');
      if(left!==null&&Number(left)<=5)window.ntToast(Number(left)===0?'That was your last of today\u2019s '+KIND[kind]+'. More tomorrow.':left+' '+KIND[kind]+' left today');
      if(res.status===429){var j=await res.clone().json();if(j&&j.error&&j.error.type==='daily_limit')window.ntToast(j.error.message)}
    }catch(e){}
    return res;
  };

  /* ---------- login screen ---------- */
  /* The one rule for carbs and fat when only calories and protein are set; every target writer uses it. */
  window.ntTargetFill=function(t,pr){
    t=Object.assign({},t||{});if(!t.calories)return t;
    if(!pr)try{pr=JSON.parse(lsGet('nt:profile')||'{}')}catch(e){pr={}}
    var sh={'low carb':.25,'high fat':.2}[(pr&&pr.style)||t.style]||.5,left=Math.max(0,t.calories-(Number(t.protein)||0)*4);
    if(t.carbs==null)t.carbs=Math.round(left*sh/4);
    if(t.fat==null)t.fat=Math.round(left*(1-sh)/9);
    return t;
  };
  function fixTarget(){
    try{
      var t=JSON.parse(lsGet('nt:daily-target')||'null');
      if(!t||!t.calories||(t.carbs!=null&&t.fat!=null))return;
      localStorage.setItem('nt:daily-target',JSON.stringify(window.ntTargetFill(t)));
    }catch(e){}
  }
  function startApp(){
    fixTarget();
    var src=document.getElementById('nt-app');
    if(!src||src.dataset.ran)return;src.dataset.ran='1';
    var s=document.createElement('script');s.text=src.textContent;document.body.appendChild(s);
  }
  async function enter(user,password){
    var status=await accountStatus();
    if(status!=='active'){if(status==='banned')banned();else gone();throw new Error(status==='banned'?'Account banned. You can no longer use DropASize.':'This account has been deleted.')}
    lsDel('ntbannotice');
    var rows=await pullFromCloud(user);
    await finishGoogleQuiz(user,rows);
    origSetSilent('nt:session','in');
    applyCoachPlan();
    if(lsGet('nt:account')===null&&lsGet('nt:profile')!==null){
      origSetSilent('nt:account',JSON.stringify({name:'Member',email:user.email,joined:new Date().toISOString().slice(0,10)}));
    }else if(lsGet('nt:account')){
      try{var a=JSON.parse(lsGet('nt:account'));delete a.pw;a.email=a.email||user.email;origSetSilent('nt:account',JSON.stringify(a))}catch(e){}
    }
    window.ntSessionEmail=user.email;
    await Promise.all([loadRole(),loadLibrary(),loadCoachMeals(),loadAvatar()]);
    startApp();
    window.dispatchEvent(new Event('nt-auth-ready'));
    setTimeout(function(){coachPlanNotice().catch(function(){})},600);
    setTimeout(hcBoot,600);
    setTimeout(showCoachNotes,1500);
    setTimeout(publishScore,4000);
    setTimeout(checkStillExists,2500);
  }

